struct draw_slot
{
  short adjustment;
  unsigned short reserved;
  void (*function)(void *);
};

struct turn_slot
{
  short adjustment;
  unsigned short reserved;
  void (*function)(void *, bool);
};

struct active_vtable
{
  char padding[72];
  draw_slot draw;
};

struct highlighted_vtable
{
  char padding[56];
  draw_slot draw;
};

struct text_vtable
{
  char padding[24];
  draw_slot draw;
};

struct quad_vtable
{
  char padding[24];
  turn_slot turn_on;
};

struct FEMenu
{
  char padding[0x74];
  active_vtable *vtable;
};

struct FEMenuEntry
{
  int entry_num;
  char padding[0x58];
  highlighted_vtable *vtable;
};

struct TextString
{
  char padding[0x4c];
  text_vtable *vtable;
};

struct PanelQuad
{
  char padding[0x194];
  quad_vtable *vtable;
};

class PanelFile
{
  char padding[0x64];

public:
  void Draw(int layer);
};

__asm__(".equ Draw__9PanelFilei, 0x001530B8");

class HighScoreFrontEnd
{
  char padding0[0x4c];
  FEMenuEntry *highlighted;
  char padding1[0x10];
  FEMenu *active;
  char padding2[4];
  TextString *helpText;
  char padding3[0x94];
  PanelFile panel;
  TextString *column_labels[5];
  TextString *info[10][5];
  PanelQuad *arrows[2][2];
  char padding4[0x30];
  int arrow_counter;
  char padding5[8];
  bool in_game;

public:
  void Draw();
};

#define DRAW_OBJECT(object)                                                   \
  ((object)->vtable->draw.function(                                           \
      (char *)(object) + (object)->vtable->draw.adjustment))

#define TURN_OBJECT(object, value)                                            \
  ((object)->vtable->turn_on.function(                                        \
      (char *)(object) + (object)->vtable->turn_on.adjustment, value))

void HighScoreFrontEnd::Draw()
{
  if (arrow_counter >= 0)
    arrow_counter--;
  if (arrow_counter < 0 && arrow_counter > -5)
  {
    arrow_counter = -5;
    TURN_OBJECT(arrows[0][0], !in_game);
    TURN_OBJECT(arrows[0][1], false);
    TURN_OBJECT(arrows[1][0], !in_game);
    TURN_OBJECT(arrows[1][1], false);
  }

  panel.Draw(0);

  if (active)
    DRAW_OBJECT(active);
  else
  {
    DRAW_OBJECT(highlighted);

    for (int i = 0; i < 5; i++)
    {
      if (i != 5 - 1 || highlighted->entry_num >= 25)
      {
        for (int j = 0; j < 10; j++)
          DRAW_OBJECT(info[j][i]);
        DRAW_OBJECT(column_labels[i]);
      }
    }

    DRAW_OBJECT(helpText);
  }
}
